//   help per-question help text   keyed by question id
//   def  definitions / tooltips   keyed by the English term (the option value)
//   ui   fixed UI / screen text   keyed by the source ENGLISH string (gettext-style)
// ─────────────────────────────────────────────────────────────────────────────
